<?php
require_once '../config/academic_service.php';require_role('guru');$pdo=db();$gid=(int)user_reference();$error='';
$q=$pdo->prepare("SELECT j.id_jadwal,j.id_kelas,k.nama_kelas,mp.nama_mapel,j.hari,j.jam_mulai FROM jadwal j JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel WHERE j.id_guru=? AND j.status='aktif' AND k.status='aktif' AND mp.status='aktif' AND EXISTS(SELECT 1 FROM tahun_ajaran scope_period WHERE scope_period.id_tahun_ajaran=j.id_tahun_ajaran AND scope_period.status='Aktif') ORDER BY j.hari,j.jam_mulai");$q->execute([$gid]);$schedules=$q->fetchAll();
$input=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$_GET;$selected=($input['id_jadwal']??'')!==''?input_id($input,'id_jadwal'):0;$date=input_date($input+['tanggal'=>date('Y-m-d')],'tanggal');
if($selected)own_schedule($selected);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{save_attendance($_POST);flash('success','Absensi disimpan dengan identitas akun pencatat dan jejak audit.');redirect('absen.php?'.http_build_query(['id_jadwal'=>$selected,'tanggal'=>$date]));}catch(Throwable $e){$error=operation_error($e);}}
$students=[];if($selected){$q=$pdo->prepare("SELECT s.nis,s.nama_siswa,a.id_absen,a.status,a.keterangan FROM jadwal j JOIN siswa s ON s.id_kelas=j.id_kelas AND s.status='aktif' LEFT JOIN absensi a ON a.nis=s.nis AND a.id_jadwal=j.id_jadwal AND a.tanggal=? WHERE j.id_jadwal=? AND j.id_guru=? ORDER BY s.nama_siswa");$q->execute([$date,$selected,$gid]);$students=$q->fetchAll();}
$page_title='Absensi Siswa';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?>
<h2>Absensi Siswa</h2>
<?php if($error):?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif;?>
<form method="get" class="card p-3 mb-4 row g-2"><div class="col-md-6"><label>Jadwal<select class="form-select" name="id_jadwal" required><option value="">Pilih jadwal</option><?php foreach($schedules as $schedule):?><option value="<?=$schedule['id_jadwal']?>" <?=$selected===(int)$schedule['id_jadwal']?'selected':''?>><?=e($schedule['nama_kelas'].' · '.$schedule['nama_mapel'].' · '.$schedule['hari'])?></option><?php endforeach;?></select></label></div><div class="col-md-4"><label>Tanggal<input class="form-control" type="date" name="tanggal" value="<?=e($date)?>" required></label></div><div class="col-md-2"><button class="btn btn-primary">Tampilkan</button></div></form>
<p>Koreksi kehadiran disimpan dengan jejak audit; arsip absensi tidak dihapus.</p>
<?php if($selected && $students):?><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>NIS</th><th>Nama</th><th>Status</th><th>Keterangan</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($students as $student):$formId='attendance-'.$student['nis'];?><tr><td><?=e($student['nis'])?></td><td><?=e($student['nama_siswa'])?></td><td><select form="<?=e($formId)?>" class="form-select" name="status"><?php foreach(['Hadir','Sakit','Izin','Alpa'] as $value):?><option value="<?=e($value)?>" <?=($student['status']??'Hadir')===$value?'selected':''?>><?=e($value)?></option><?php endforeach;?></select></td><td><input form="<?=e($formId)?>" class="form-control" name="keterangan" value="<?=e($student['keterangan']??'')?>"></td><td><form id="<?=e($formId)?>" method="post"><?=csrf_field()?><input type="hidden" name="id_jadwal" value="<?=$selected?>"><input type="hidden" name="tanggal" value="<?=e($date)?>"><input type="hidden" name="nis" value="<?=e($student['nis'])?>"><?php if($student['id_absen']):?><input type="hidden" name="id_absen" value="<?=$student['id_absen']?>"><?php endif;?><button class="btn btn-success" name="action" value="save">Simpan</button></form></td></tr><?php endforeach;?>
</tbody></table></div></div><?php endif;?>
<?php require '../includes/footer.php';
